import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"发布与回滚策略","description":"","frontmatter":{"title":"发布与回滚策略","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/delivery/release-strategy.md","filePath":"frontend/decisions/delivery/release-strategy.md","lastUpdated":1785589115000}'),l={name:"frontend/decisions/delivery/release-strategy.md"};function i(o,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="发布与回滚策略" tabindex="-1">发布与回滚策略 <a class="header-anchor" href="#发布与回滚策略" aria-label="Permalink to &quot;发布与回滚策略&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>部署是把制品放入生产环境，发布是让用户获得新行为。滚动、蓝绿和金丝雀描述流量如何进入新制品，Feature Flag 描述功能对谁生效；这些机制可以组合，不能当作同一层面的互斥选项。</p><p>实现细节参见<a href="/frontend/guide/engineering/reliability/feature-rollout">Feature Flag 与渐进式发布</a>和<a href="/frontend/guide/engineering/reliability/recovery">故障隔离与恢复设计</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>前端静态资源通常被 CDN 长缓存，用户还可能保持旧页面数小时；后端和数据契约必须同时兼容新旧客户端。简单“回滚到上一个版本”无法撤销已发送消息、数据库写入或第三方副作用。</p><p>发布策略应从失败影响、可观察信号、回滚时间和状态变更可逆性开始。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-发布硬约束" tabindex="-1">2.1 发布硬约束 <a class="header-anchor" href="#_2-1-发布硬约束" aria-label="Permalink to &quot;2.1 发布硬约束&quot;">​</a></h3><ul><li>制品不可变、可追溯，HTML 与资源版本不会错误混配；</li><li>API 在发布窗口内兼容新旧客户端；</li><li>数据迁移遵循先扩展、后切换、再收缩，不依赖代码回滚恢复旧 Schema；</li><li>高风险功能有负责人、停止阈值和经过演练的关闭路径；</li><li>权限、安全和合规规则不能通过实验分流绕过。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较失败影响范围、检测速度、流量分层、用户一致性、缓存、状态迁移、基础设施成本、操作复杂度、回滚时间和验证证据。</p><h2 id="_3-候选机制" tabindex="-1">3. 候选机制 <a class="header-anchor" href="#_3-候选机制" aria-label="Permalink to &quot;3. 候选机制&quot;">​</a></h2><h3 id="_3-1-全量发布" tabindex="-1">3.1 全量发布 <a class="header-anchor" href="#_3-1-全量发布" aria-label="Permalink to &quot;3.1 全量发布&quot;">​</a></h3><p>所有用户立即获得新版本。适合低风险、容易回滚和无持久状态的变更。反馈快，但一次故障影响最大。</p><h3 id="_3-2-滚动或蓝绿部署" tabindex="-1">3.2 滚动或蓝绿部署 <a class="header-anchor" href="#_3-2-滚动或蓝绿部署" aria-label="Permalink to &quot;3.2 滚动或蓝绿部署&quot;">​</a></h3><p>滚动逐批替换实例，基础设施成本较低；蓝绿保留两套完整环境，通过切换流量实现快速回退。两者解决制品部署，不自动控制某项功能的用户范围。</p><h3 id="_3-3-金丝雀发布" tabindex="-1">3.3 金丝雀发布 <a class="header-anchor" href="#_3-3-金丝雀发布" aria-label="Permalink to &quot;3.3 金丝雀发布&quot;">​</a></h3><p>按实例、流量或用户群逐步扩大新制品，需要稳定分桶、版本指标和自动停止。适合能够快速观测错误与性能的高风险变更；低流量业务可能很久无法获得统计证据。</p><h3 id="_3-4-feature-flag" tabindex="-1">3.4 Feature Flag <a class="header-anchor" href="#_3-4-feature-flag" aria-label="Permalink to &quot;3.4 Feature Flag&quot;">​</a></h3><p>把功能启用与部署解耦，可按租户、角色或随机分组开放。适合业务功能和实验，但增加代码分支、配置依赖和清理责任。安全权限必须在服务端独立执行，不能依赖前端 Flag 隐藏。</p><h3 id="_3-5-操作型开关与降级" tabindex="-1">3.5 操作型开关与降级 <a class="header-anchor" href="#_3-5-操作型开关与降级" aria-label="Permalink to &quot;3.5 操作型开关与降级&quot;">​</a></h3><p>Kill Switch 用于关闭高风险路径，降级则保留有限能力。它们应经过演练，并与产品实验 Flag 分开管理权限和审计。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>控制对象</th><th>回退速度</th><th>主要限制</th></tr></thead><tbody><tr><td>全量发布</td><td>整个版本</td><td>重新部署或切资源</td><td>影响面大</td></tr><tr><td>滚动</td><td>实例批次</td><td>停止并回滚批次</td><td>新旧实例需兼容</td></tr><tr><td>蓝绿</td><td>环境流量</td><td>快速切换</td><td>双环境成本、状态仍需兼容</td></tr><tr><td>金丝雀</td><td>少量流量/用户</td><td>停止扩量</td><td>需要分桶和版本指标</td></tr><tr><td>Feature Flag</td><td>功能行为</td><td>通常最快</td><td>分支和配置债务</td></tr><tr><td>Kill Switch</td><td>高风险能力</td><td>最快</td><td>需要预先设计降级结果</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是结算页升级：新前端静态资源、新优惠接口和新的优惠快照字段共同上线；日订单 10 万，支付成功率是核心指标。旧客户端最长可能存活 24 小时。</p><p>推荐组合：</p><ol><li>服务端先扩展为同时接受旧请求和新优惠快照，数据库只增加可空字段；</li><li>新前端以不可变资源部署，功能默认关闭；</li><li>先向内部租户开放，再按稳定用户 ID 灰度 1%、5%、20%、50%、100%；</li><li>每阶段至少观察一个完整业务高峰，监控支付成功率、接口错误、优惠差异和前端异常；</li><li>指标越界时关闭 Flag，使客户端回到旧结算路径；服务端兼容至少保留 7 天；</li><li>全量稳定后删除旧客户端分支，最后在确认无旧流量后收缩 Schema。</li></ol><p>这里的首选回退是关闭功能，而不是重新部署静态资源，因为旧路径已经随同一制品发布并经过验证。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>渐进发布把失败影响限制在小范围，并提供真实流量证据。代价是新旧路径、指标分组、Flag 配置和兼容服务同时存在。每个 Flag 必须有类型、负责人、创建日期、全量日期和删除期限。</p><p>回滚只能撤销代码行为，不能撤销已经创建的订单或向第三方发出的支付。副作用需要幂等、补偿和人工处置方案。</p><p>前端 CDN 回滚还要处理 HTML、资源清单和 Service Worker 缓存。旧资源在兼容窗口内应继续可访问，不能覆盖同名文件。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>安全补丁需要迅速全量时，长时间实验可能扩大风险，但仍需监控和可回退制品。</li><li>低流量功能无法依靠 1% 灰度获得有效信号，可按内部用户或时间窗口验证。</li><li>不要用前端 Flag 作为权限控制。</li><li>数据破坏性迁移不能假设应用回滚会恢复旧数据。</li><li>永久 Flag 会形成难以测试的组合，应在稳定后删除。</li></ul><h2 id="_8-填写完成的发布记录" tabindex="-1">8. 填写完成的发布记录 <a class="header-anchor" href="#_8-填写完成的发布记录" aria-label="Permalink to &quot;8. 填写完成的发布记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>变更</td><td>新结算页与优惠快照</td></tr><tr><td>风险</td><td>支付失败、优惠差异、旧客户端不兼容、不可逆订单副作用</td></tr><tr><td>部署</td><td>服务端先扩展；前端不可变静态制品</td></tr><tr><td>发布</td><td>内部 → 1% → 5% → 20% → 50% → 100%</td></tr><tr><td>分桶</td><td>稳定用户 ID，用户会话内不切换版本</td></tr><tr><td>停止阈值</td><td>支付成功率下降 0.3 个百分点或优惠差异超过 0.1%</td></tr><tr><td>回退</td><td>关闭新结算 Flag；保留旧服务契约；异常订单走补偿流程</td></tr><tr><td>负责人</td><td>结算产品、前端、服务端和值班负责人共同签署</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>每次高风险发布后复盘一次；当回退超过目标时间、Flag 超期率高于 10%、版本指标无法区分、旧客户端存活窗口变化，或数据迁移连续阻碍回滚时调整策略。发布能力本身也要演练，不能等故障时首次验证。</p>',40)])])}const p=a(l,[["render",i]]);export{_ as __pageData,p as default};
